INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) VALUES ('5604c5ae-d10d-4ca3-920d-dd3592278777','e9ebefcd-c496-45e8-b816-a79f8442ba85',$$Council Member Negrete is a vocal public-safety advocate who led the task force addressing illegal vending and crime on the Santa Monica Pier that became the DART team mitigating crime along the beach, an enforcement-supportive posture.$$,ARRAY['https://lananegrete.com/']::text[]::text[]) ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) VALUES ('5604c5ae-d10d-4ca3-920d-dd3592278777','6fbf39ae-6b19-4182-b4c2-6a8d25c86c0f',3.0) ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) VALUES ('5604c5ae-d10d-4ca3-920d-dd3592278777','6fbf39ae-6b19-4182-b4c2-6a8d25c86c0f',$$Through the Council's Ad Hoc Committee on Homelessness, Negrete works cooperatively with agencies and emphasizes mental-health solutions, a pragmatic, balanced approach to homelessness.$$,ARRAY['https://www.mygovtools.org/blog/lana-negrete-santa-monica-mayor.html']::text[]::text[]) ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
